#!/usr/bin/env python3
from pathlib import Path
import sys

ROOT = Path(sys.argv[1]).resolve() if len(sys.argv) > 1 else Path.cwd()

def replace_once(path_str, old, new, label):
    path = ROOT / path_str
    if not path.exists():
        raise SystemExit(f"Missing file: {path}")
    text = path.read_text(encoding="utf-8")
    if new in text and old not in text:
        print(f"SKIP  {label} (already patched)")
        return
    if old not in text:
        raise SystemExit(f"Could not patch {label}: expected block not found in {path_str}.")
    path.write_text(text.replace(old, new, 1), encoding="utf-8")
    print(f"PATCH {label}")

replace_once("components/warping/shapes-catalogue.tsx", "import {\n  useEffect,\n  useMemo,\n  useState,\n} from \"react\";\n", "import {\n  useEffect,\n  useMemo,\n  useRef,\n  useState,\n} from \"react\";\n", "add useRef for progressive Shapes rendering")
replace_once("components/warping/shapes-catalogue.tsx", "  const [nature, setNature] = useState(\"\");\n\n  const schools = useMemo(\n", "  const [nature, setNature] = useState(\"\");\n\n  const SHAPES_BATCH_SIZE = 24;\n\n  const [\n    visibleCount,\n    setVisibleCount,\n  ] = useState(\n    SHAPES_BATCH_SIZE,\n  );\n\n  const loadMoreRef =\n    useRef<HTMLDivElement>(null);\n\n  const schools = useMemo(\n", "add progressive Shapes state")
replace_once("components/warping/shapes-catalogue.tsx", "  useEffect(() => {\n    const ids =\n      filtered.map((shape) => shape.id);\n", "  const visibleShapes =\n    useMemo(\n      () =>\n        filtered.slice(\n          0,\n          visibleCount,\n        ),\n      [\n        filtered,\n        visibleCount,\n      ],\n    );\n\n  useEffect(() => {\n    setVisibleCount(\n      SHAPES_BATCH_SIZE,\n    );\n  }, [\n    q,\n    level,\n    school,\n    movement,\n    target,\n    nature,\n  ]);\n\n  useEffect(() => {\n    const target =\n      loadMoreRef.current;\n\n    if (\n      !target ||\n      visibleCount >=\n        filtered.length\n    ) {\n      return;\n    }\n\n    const observer =\n      new IntersectionObserver(\n        (entries) => {\n          if (\n            entries.some(\n              (entry) =>\n                entry.isIntersecting,\n            )\n          ) {\n            setVisibleCount(\n              (current) =>\n                Math.min(\n                  current +\n                    SHAPES_BATCH_SIZE,\n                  filtered.length,\n                ),\n            );\n          }\n        },\n        {\n          rootMargin:\n            \"900px 0px\",\n        },\n      );\n\n    observer.observe(target);\n\n    return () => {\n      observer.disconnect();\n    };\n  }, [\n    filtered.length,\n    visibleCount,\n  ]);\n\n  useEffect(() => {\n    function revealAndScroll(\n      shapeId: string,\n    ) {\n      const index =\n        filtered.findIndex(\n          (shape) =>\n            shape.id === shapeId,\n        );\n\n      if (index < 0) {\n        return;\n      }\n\n      setVisibleCount(\n        (current) =>\n          Math.max(\n            current,\n            index + 1,\n          ),\n      );\n\n      window.requestAnimationFrame(\n        () => {\n          window.requestAnimationFrame(\n            () => {\n              document\n                .getElementById(\n                  `shape-${shapeId}`,\n                )\n                ?.scrollIntoView({\n                  behavior:\n                    \"smooth\",\n                  block: \"start\",\n                });\n            },\n          );\n        },\n      );\n    }\n\n    function handleJump(\n      event: Event,\n    ) {\n      const shapeId =\n        (\n          event as CustomEvent<{\n            id?: string;\n          }>\n        ).detail?.id;\n\n      if (shapeId) {\n        revealAndScroll(\n          shapeId,\n        );\n      }\n    }\n\n    window.addEventListener(\n      \"sepulchria:shape-jump\",\n      handleJump,\n    );\n\n    const hash =\n      window.location.hash;\n\n    if (\n      hash.startsWith(\n        \"#shape-\",\n      )\n    ) {\n      revealAndScroll(\n        hash.slice(\n          \"#shape-\".length,\n        ),\n      );\n    }\n\n    return () => {\n      window.removeEventListener(\n        \"sepulchria:shape-jump\",\n        handleJump,\n      );\n    };\n  }, [filtered]);\n\n  useEffect(() => {\n    const ids =\n      filtered.map((shape) => shape.id);\n", "add progressive rendering and deep-link reveal")
replace_once("components/warping/shapes-catalogue.tsx", "        {filtered.map((shape) => (\n          <ShapeArticle\n            key={shape.id}\n            shape={shape}\n          />\n        ))}\n\n        {!filtered.length ? (\n", "        {visibleShapes.map((shape) => (\n          <ShapeArticle\n            key={shape.id}\n            shape={shape}\n          />\n        ))}\n\n        {visibleCount <\n        filtered.length ? (\n          <div\n            ref={loadMoreRef}\n            className=\"col-span-full flex min-h-16 items-center justify-center border border-[rgb(var(--sep-colour-59432c))]/25 bg-[rgb(var(--sep-colour-100c09))] px-4 py-3 text-[8px] uppercase tracking-[0.12em] text-[rgb(var(--sep-colour-756957))]\"\n          >\n            Showing{\" \"}\n            {Math.min(\n              visibleCount,\n              filtered.length,\n            )}{\" \"}\n            of {filtered.length} Shapes\n          </div>\n        ) : null}\n\n        {!filtered.length ? (\n", "render /warping Shapes progressively")
replace_once("components/portal/portal-context-panel.tsx", "const jump=(id:string)=>{const el=document.getElementById(`shape-${id}`);if(el){el.scrollIntoView({behavior:\"smooth\",block:\"start\"});window.history.replaceState(null,\"\",`#shape-${id}`)}};", "const jump=(id:string)=>{window.history.replaceState(null,\"\",`#shape-${id}`);const el=document.getElementById(`shape-${id}`);if(el){el.scrollIntoView({behavior:\"smooth\",block:\"start\"});return;}window.dispatchEvent(new CustomEvent(\"sepulchria:shape-jump\",{detail:{id}}));};", "keep Shape navigator working with progressive rendering")
replace_once("app/(portal)/admin/shapes/page.tsx", "import {\n  requireAdminSection,\n} from \"@/lib/auth/require-staff\";\n", "import Link from \"next/link\";\n\nimport {\n  requireAdminSection,\n} from \"@/lib/auth/require-staff\";\n", "add Link to admin Shapes")
replace_once("app/(portal)/admin/shapes/page.tsx", "type Props={searchParams?:Promise<{success?:string;error?:string}>}; type S=Record<string,any>;\n", "type Props={searchParams?:Promise<{success?:string;error?:string;shape?:string}>}; type S=Record<string,any>;\n", "allow selected Shape query parameter")

